fn md_carrier_without_bot_session_is_none() {
    let root = crate::test_tmp_root::resolve_tmp_root().join("vc_x1_bot_session_md_absent");
    std::fs::remove_dir_all(&root).ok();
    std::fs::create_dir_all(&root).unwrap();
